// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(address actor, uint256 blockNum) public {
        uint256 value = 10 ether;
        vm.assume(actor != address(0));
        vm.assume(blockNum > 0);
        vm.roll(blockNum);
        vm.warp(block.timestamp + 1);
        vm.deal(actor, value);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: value}("");
        assertTrue(ok);
        uint256 balanceAfter = address(c).balance;
        assertTrue((blockNum % 15 == 0 && balanceAfter == 0) || (blockNum % 15 != 0 && balanceAfter == value));
    }
}
